/** A committed tombstone, never a NOT_FOUND inference. TenantTransaction locks the tenant watermark before all three commands. */
@org.springframework.stereotype.Component public final class FormalCapabilityCancellation {
 private final EnterpriseAccess access;private final FormalCapabilityCancellationMapper mapper;private final PermissionMapper permissions;private final ResourceReadAuthority resources;private final AgentPublicationJournal journal;private final AgentPublicationSchema originalSchema;private final com.ruoyi.medical.identity.IdentityDirectoryPolicy settings;private final FormalCapabilityCancellationSchema schema;private final PermissionSchema json;
 public FormalCapabilityCancellation(EnterpriseAccess access,FormalCapabilityCancellationMapper mapper,PermissionMapper permissions,ResourceReadAuthority resources,AgentPublicationJournal journal,AgentPublicationSchema originalSchema,com.ruoyi.medical.identity.IdentityDirectoryPolicy settings,FormalCapabilityCancellationSchema schema,PermissionSchema json){this.access=access;this.mapper=mapper;this.permissions=permissions;this.resources=resources;this.journal=journal;this.originalSchema=originalSchema;this.settings=settings;this.schema=schema;this.json=json;}
 public JsonNode cancel(ApplicationSessionIdentity.Verified actor,String context,String key,byte[] body){FormalCapabilityCancellationSchema.key(key);return access.execute(actor,a->checked(()->{
  if(!a.context().context_revision().equals(context))reject(ErrorCode.CONTEXT_CHANGED);
  var request=schema.request("CancelRequest",body);String kind=request.required("original_kind").textValue(),originalKey=request.required("original_key").textValue();var original=request.required("original_request");
  String project=original.required("project_id").isNull()?null:original.required("project_id").asText(),classification=settings.classification();
  var scope=ownerScope(a.context().tenant_id(),project);var grant=resources.require(a,scope,"configuration.read","AGENT_PUBLICATION");
  var query=new HashMap<String,Object>();query.put("userId",a.actorId());query.put("key",key);query.put("originalKind",kind);query.put("originalKey",originalKey);
  var byKey=mapper.cancellationByKey(query);if(byKey.size()>1)reject(ErrorCode.CONTENT_MISMATCH);if(!byKey.isEmpty()){var fixed=verifyStored(a,byKey.get(0));if(!byKey.get(0).cancelKey().equals(key))reject(ErrorCode.CONTENT_MISMATCH);if(!fixed.required("request").equals(request))reject(ErrorCode.IDEMPOTENCY_CONFLICT);return fixed.required("receipt");}
  var previous=mapper.cancellationByOriginal(query);if(previous.size()>1)reject(ErrorCode.CONTENT_MISMATCH);if(!previous.isEmpty()){verifyStored(a,previous.get(0));reject(ErrorCode.IDEMPOTENCY_CONFLICT);}
  JsonNode completed=originalReceipt(a,originalKey,original);
  String id=UUID.randomUUID().toString(),operation=UUID.randomUUID().toString(),audit=UUID.randomUUID().toString(),event=UUID.randomUUID().toString();var now=permissions.databaseTime();
  var receipt=json.object().put("schema_version","1.0.0").put("status",completed==null?"CANCELLED":"COMPLETED").put("cancellation_id",id).put("operation_id",operation).put("tenant_id",a.context().tenant_id()).put("actor_id",a.actorId()).put("original_kind",kind).put("original_key",originalKey).put("original_request_sha256",schema.hash(original)).put("cancellation_request_sha256",schema.hash(request)).put("recorded_at",now.toInstant(ZoneOffset.UTC).toString());receipt.set("receipt",completed==null?json.tree(null):completed);schema.validate("CancelReceipt",receipt);
  var fixed=json.object().put("schema_version","1.0.0").put("session_id",actor.sessionId()).put("cancel_key",key).put("audit_id",audit).put("event_id",event);fixed.set("read_grant",json.tree(Map.of("grant_id",grant.grantId(),"revision",grant.revision().toString())));fixed.set("context",json.tree(a.context()));fixed.set("request",request);fixed.set("receipt",receipt);schema.validate("Cancellation",fixed);
  var v=new HashMap<String,Object>();v.put("userId",a.actorId());v.put("projectId",project);v.put("classification",classification);v.put("cancellationId",id);v.put("operationId",operation);v.put("key",key);v.put("originalKind",kind);v.put("originalKey",originalKey);v.put("originalHash",schema.hash(original));v.put("requestHash",schema.hash(request));v.put("fixedJson",schema.canonical(fixed));v.put("contentHash",schema.hash(fixed));v.put("receiptJson",schema.canonical(receipt));v.put("manifest",schema.manifest());v.put("now",now);
  String witness=schema.canonical(Map.of("schema_version","1.0.0","cancellation_id",id,"content_sha256",schema.hash(fixed)));
  one(mapper.insertCancelOperation(v));one(permissions.saveAudit(a.actorId(),project,audit,"formal.capability.request.cancelled",witness,operation,schema.manifest(),classification));one(permissions.saveEvent(a.actorId(),event,id,"1","formal.capability.request.cancelled",witness));one(mapper.insertCancellation(v));
  verifyStored(a,AgentPublicationJournal.one(mapper.cancellationByKey(query)));if(!grant.equals(resources.require(a,scope,"configuration.read","AGENT_PUBLICATION")))reject(ErrorCode.SCOPE_STALE);return receipt;
 }));}
 public JsonNode recover(ApplicationSessionIdentity.Verified actor,String context,String key){FormalCapabilityCancellationSchema.key(key);return access.execute(actor,a->checked(()->{if(!a.context().context_revision().equals(context))reject(ErrorCode.CONTEXT_CHANGED);var rows=mapper.cancellationByKey(Map.of("userId",a.actorId(),"key",key));if(rows.size()>1)reject(ErrorCode.CONTENT_MISMATCH);var result=json.object().put("schema_version","1.0.0");if(rows.isEmpty())return result.put("status","NOT_FOUND").putNull("receipt");var row=rows.get(0);resources.require(a,ownerScope(a.context().tenant_id(),row.projectId()),"configuration.read","AGENT_PUBLICATION");result.put("status","FOUND");if(!row.cancelKey().equals(key))reject(ErrorCode.CONTENT_MISMATCH);result.set("receipt",verifyStored(a,row).required("receipt"));return result;}));}
 private JsonNode originalReceipt(EnterpriseAccess.Admission a,String key,JsonNode request)throws IOException {
  var row=journal.prior(a,"FORMAL_CAPABILITY_AUTHOR",key,request);if(row==null)return null;
  if(!row.createdBy().equals(a.actorId())||!row.idempotencyKey().equals(key)||!row.kind().equals("FORMAL_CAPABILITY_AUTHOR")||!originalSchema.read(row.requestJson()).equals(request))reject(ErrorCode.CONTENT_MISMATCH);
  return originalSchema.validate("Receipt",originalSchema.read(row.receiptJson()));
 }
 private JsonNode verifyStored(EnterpriseAccess.Admission a,FormalCapabilityCancellationMapper.Cancellation row)throws IOException{
  var fixed=verify(mapper,schema,row);var actual=originalReceipt(a,row.originalKey(),fixed.required("request").required("original_request"));
  if(actual==null?!fixed.required("receipt").required("receipt").isNull():!actual.equals(fixed.required("receipt").required("receipt")))reject(ErrorCode.CONTENT_MISMATCH);return fixed;
 }
 /** Called inside the original author transaction before any new capability write or grant-dependent work. */
 public void requireNotCancelled(EnterpriseAccess.Admission a,String key,JsonNode request)throws IOException{
  var rows=mapper.cancellationByOriginal(Map.of("userId",a.actorId(),"originalKind","FORMAL_CAPABILITY_AUTHOR","originalKey",key));if(rows.size()>1)reject(ErrorCode.CONTENT_MISMATCH);if(rows.isEmpty())return;
  var row=rows.get(0);var fixed=verifyStored(a,row);if(!row.originalKey().equals(key)||!row.originalKind().equals("FORMAL_CAPABILITY_AUTHOR"))reject(ErrorCode.CONTENT_MISMATCH);
  if(!schema.hash(request).equals(row.originalHash()))reject(ErrorCode.IDEMPOTENCY_CONFLICT);
  if(fixed.required("receipt").required("status").asText().equals("CANCELLED"))reject(ErrorCode.ACTION_STALE);
 }
 static PermissionProtocol.Scope ownerScope(String tenant,String project){return new PermissionProtocol.Scope(tenant,project,project==null?"ENTERPRISE":"PROJECT",project==null?tenant:project);}
 static JsonNode verify(FormalCapabilityCancellationMapper mapper,FormalCapabilityCancellationSchema schema,FormalCapabilityCancellationMapper.Cancellation row)throws IOException{
  var f=schema.validate("Cancellation",schema.read(row.fixedJson()));var r=schema.validate("CancelReceipt",f.required("receipt"));var q=f.required("request");
  if(!row.tenantId().equals(TenantScope.requireCurrent().tenantId())||!row.createdBy().equals(TenantScope.requireCurrent().subjectId())||!row.tenantId().equals(r.required("tenant_id").asText())||!row.tenantId().equals(f.required("context").required("tenant_id").asText())||!row.createdBy().equals(r.required("actor_id").asText())||!row.cancellationId().equals(r.required("cancellation_id").asText())||!row.operationId().equals(r.required("operation_id").asText())||!row.cancelKey().equals(f.required("cancel_key").asText())||!row.originalKind().equals(q.required("original_kind").asText())||!row.originalKind().equals(r.required("original_kind").asText())||!row.originalKey().equals(q.required("original_key").asText())||!row.originalKey().equals(r.required("original_key").asText())||!row.originalHash().equals(schema.hash(q.required("original_request")))||!row.originalHash().equals(r.required("original_request_sha256").asText())||!schema.hash(q).equals(r.required("cancellation_request_sha256").asText())||!schema.hash(f).equals(row.contentHash())||!"1.0.0".equals(row.schemaVersion())||!schema.manifest().equals(row.manifest())||!Instant.parse(row.createdAt()).equals(Instant.parse(r.required("recorded_at").asText())))reject(ErrorCode.CONTENT_MISMATCH);
  if(!Objects.equals(row.projectId(),q.required("original_request").required("project_id").isNull()?null:q.required("original_request").required("project_id").asText()))reject(ErrorCode.CONTENT_MISMATCH);
  if(r.required("status").asText().equals("CANCELLED")!=r.required("receipt").isNull())reject(ErrorCode.CONTENT_MISMATCH);
  if(!r.required("receipt").isNull()){schema.validate("Receipt",r.required("receipt"));if(!row.originalHash().equals(r.required("receipt").required("request_body_sha256").asText()))reject(ErrorCode.CONTENT_MISMATCH);}
  var v=new HashMap<String,Object>();v.put("userId",TenantScope.requireCurrent().subjectId());v.put("projectId",row.projectId());v.put("classification",row.classification());v.put("cancellationId",row.cancellationId());v.put("operationId",row.operationId());v.put("key",row.cancelKey());v.put("requestHash",schema.hash(q));v.put("manifest",row.manifest());v.put("createdAt",LocalDateTime.ofInstant(Instant.parse(row.createdAt()),ZoneOffset.UTC));v.put("auditId",f.required("audit_id").asText());v.put("eventId",f.required("event_id").asText());
  if(!schema.read(AgentPublicationJournal.one(mapper.cancellationOperation(v))).equals(r))reject(ErrorCode.CONTENT_MISMATCH);
  var witness=schema.read(schema.canonical(Map.of("schema_version","1.0.0","cancellation_id",row.cancellationId(),"content_sha256",row.contentHash())));
  if(!schema.read(AgentPublicationJournal.one(mapper.cancellationAudit(v))).equals(witness)||!schema.read(AgentPublicationJournal.one(mapper.cancellationEvent(v))).equals(witness))reject(ErrorCode.CONTENT_MISMATCH);return f;
 }
 private static void one(int count){if(count!=1)reject(ErrorCode.REVISION_CONFLICT);}private interface Work<T>{T run()throws IOException;}private static <T>T checked(Work<T> w){try{return w.run();}catch(IOException e){throw new SchemaRejection(ErrorCode.CONTENT_MISMATCH);}}private static void reject(ErrorCode c){throw new TenantAccessException(c);}
}
